    SpeciesCatalogEntry('Juniperus procumbens', 'Cupressaceae', SpeciesCategory.tree, fr: 'Genévrier rampant (bonsaï)', en: 'Japanese garden juniper (bonsai)', de: 'Kriech-Wacholder (Bonsai)', it: 'Ginepro (bonsai)'),
    SpeciesCatalogEntry('Ulmus parvifolia', 'Ulmaceae', SpeciesCategory.tree, fr: 'Orme de Chine (bonsaï)', en: 'Chinese elm (bonsai)', de: 'Chinesische Ulme (Bonsai)', it: 'Olmo cinese (bonsai)'),
  ];

  static List<SpeciesCatalogEntry> byCategory(SpeciesCategory? category) =>
      category == null ? entries : entries.where((e) => e.category == category).toList();

  static List<SpeciesCatalogEntry> search(String query) {
    final q = query.trim();
    if (q.isEmpty) return entries;
    return entries.where((e) => e.matches(q)).toList();
  }

  /// Entrée exacte pour un nom scientifique (insensible à la casse).
  static SpeciesCatalogEntry? find(String scientificName) {
    final n = scientificName.trim().toLowerCase();
    for (final e in entries) {
      if (e.scientificName.toLowerCase() == n) return e;
    }
    return null;
  }
}
